import sys
import os

def count_lines_with_term(file_path, term):
    try:
        with open(file_path, 'r') as f:
            lines = f.readlines()
        # Remove trailing newline if it exists
        if lines and lines[-1] == '\n':
            lines.pop()
        return sum(1 for line in lines if term in line)
    except Exception:
        return -1

if __name__ == '__main__':
    if len(sys.argv) != 3:
        sys.exit(1)

    term = sys.argv[1]
    log_path = sys.argv[2]
    ok_count = 0
    fail_count = 0

    for line in sys.stdin:
        file_path = line.strip()
        count = count_lines_with_term(file_path, term)
        if count == -1:
            status = 'FAIL'
            fail_count += 1
            count = -1
        else:
            status = 'OK'
            ok_count += 1

        with open(log_path, 'a') as log_file:
            log_file.write(f'{status}\t{file_path}\t{count}\n')

    print(f'{ok_count} processed, {fail_count} failed')
    sys.exit(0 if fail_count == 0 else 1)

import sys
import os

def process_file(file_path, search_term):
