            count = 0
            for line in f:
                if search_term in line:
                    count += 1
            return count
    except (IOError, OSError):
        return -1

def main():
    search_term = sys.stdin.readline().strip()
    log_path = sys.stdin.readline().strip()
    paths = [line.strip() for line in sys.stdin if line.strip()]

    ok_count = 0
    fail_count = 0

    with open(log_path, 'a') as log_file:
        for path in paths:
            count = process_file(path, search_term)
            status = 'OK' if count != -1 else 'FAIL'
            log_file.write(f"{status}\t{path}\t{count}\n")
            if status == 'OK':
                ok_count += 1
            else:
                fail_count += 1

    sys.stdout.write(f"{ok_count} processed, {fail_count} failed\n")
    sys.exit(fail_count > 0)

