    file_paths = [line.strip() for line in sys.stdin if line.strip()]

    ok_count = 0
    fail_count = 0
    log_file = open(log_path, 'a') if os.path.exists(log_path) else open(log_path, 'w')

    for path in file_paths:
        try:
            with open(path, 'r') as f:
                count = 0
                for line in f:
                    if search_term in line:
                        count += 1
                status = 'OK' if count > 0 else 'FAIL'
                log_file.write(f"{status} {path} {count}\n")
                if status == 'OK':
                    ok_count += 1
                else:
                    fail_count += 1
        except (IOError, OSError):
            log_file.write(f"FAIL {path} -1\n")
            fail_count += 1

    log_file.close()
    sys.stdout.write(f"{ok_count} processed, {fail_count} failed\n")
    sys.exit(fail_count != 0)

if __name__ == "__main__":
