import sys
import os
from pathlib import Path

def process_file(path, search_term):
    try:
        with open(path, 'r', encoding='utf-8') as file:
            count = 0
            for line in file:
                if search_term in line:
                    count += 1
            return count
    except Exception as e:
        return str(e)

def main():
    search_term = sys.stdin.readline().strip()
    log_file = Path('linereport.log')

    for path_line in sys.stdin:
        path = path_line.strip()
        if not path:
            continue
        try:
            count = process_file(path, search_term)
            log_file.write_text(log_file.read_text() + f"OK {path} {count}\n", encoding='utf-8')
        except Exception as e:
            log_file.write_text(log_file.read_text() + f"FAIL {path} {str(e)}\n", encoding='utf-8')

if __name__ == "__main__":
    main()

