                    for line in file:
                        if search_term in line:
                            count += 1
                    log_file.write(f"OK {path} {count}\n")
            except Exception as e:
                log_file.write(f"FAIL {path} {str(e)}\n")

if __name__ == "__main__":
    process_search_term_and_paths()
